import{_ as t,C as r,o,c as s,a6 as n,E as d}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"設定とキーボード操作を見つける","description":"","frontmatter":{"title":"設定とキーボード操作を見つける","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"48c7e05eee7dde90ae5d819d5b58067138e316a6ad074ee9aa13bf1bd4973449","order":10},"headers":[],"relativePath":"ja/user/preferences/index.md","filePath":"ja/user/preferences/index.md","lastUpdated":1794611623000}'),i={name:"ja/user/preferences/index.md"};function l(c,e,p,u,f,h){const a=r("DemoFrame");return o(),s("div",null,[e[0]||(e[0]=n('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">設定とキーボード操作を見つける <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;設定とキーボード操作を見つける {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>アプリの言語と正しい設定場所を見つけ、対応キーボード操作を快適に使います。デスクトップウィンドウを開いておく必要があります。ネットワークは設定するサービスが必要とする場合だけ使います。</p><h2 id="find-the-relevant-setting" tabindex="-1">対象の設定を探す <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;対象の設定を探す {#find-the-relevant-setting}&quot;">​</a></h2><ol><li><strong>設定 → 一般</strong> で表示言語を選びます。現在は英語 (<code>en</code>)、スペイン語 (<code>es</code>)、ポルトガル語 (<code>pt</code>)、フランス語 (<code>fr</code>)、簡体字中国語 (<code>zh</code>)、日本語 (<code>ja</code>) です。言語選択で TikTok イベント識別子やプラグイン API 名は変わりません。</li><li>一般の更新設定で、チャンネル、自動確認、通知、対応時の手動確認を調べます。自動確認は任意です。署名付き更新の可否は、そのビルドで公開された署名設定に依存します。</li><li><strong>アカウント</strong> で Cloud ID と診断、<strong>共同作業</strong> で所有者のアクセス、ホストが対応する場合は <strong>チーム</strong> を使います。</li><li><strong>プラグイン</strong> で共通設定と各プラグインの設定/接続を開きます。プラグインのサービス認証情報は一般には入力しません。</li><li>共有実行時値は <strong>自動化 → 変数</strong>、付与ルールは <strong>ポイント</strong>、ウィジェット設計は <strong>オーバーレイ</strong> にあります。影響する機能の近くに配置されています。</li></ol><p>自動インストールは実験段階で、現行リリースのビルド条件により無効です。自動確認の設定が見えても自動インストールを約束しません。<a href="./../updates.html">更新手順</a> に従い、版の変更前に<a href="./backups.html">バックアップ</a> を取ります。</p><h2 id="use-supported-keyboard-controls" tabindex="-1">対応するキーボード操作を使う <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;対応するキーボード操作を使う {#use-supported-keyboard-controls}&quot;">​</a></h2><p>Tab と Shift+Tab で通常の操作欄間を移動し、Enter/Space でフォーカス中のボタンを実行します。オーバーレイのデザインインスペクターでは Ctrl/Meta+Z で元に戻し、Ctrl/Meta+Shift+Z または Ctrl/Meta+Y でやり直します。テキスト入力は独自の取り消しを維持します。これは編集用で、全体の自動化ホットキーではありません。</p><p>他の操作が処理していなければ Escape で狭幅のナビゲーションを閉じます。ダイアログやエディターは未保存確認などのため独自に Escape を扱う場合があります。グローバルホットキーの自動化には、互換プラグインと通知されたバックエンド機能が必要です。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;期待される結果・提供状況と対処 {#expected-result-status-and-recovery}&quot;">​</a></h2><p>これらの設定とローカルキーボード操作を利用できますが、アクセシビリティや各環境の完全な適合は主張しません。ラベル付きボタン、読みやすいウィンドウサイズを使い、動きが気になるならフィードを停止します。設定が見えなければリセット前に担当ページとホスト機能を確認します。操作不能は<a href="./troubleshooting.html">トラブルシューティング</a>、よくある違いは <a href="./faq.html">FAQ</a> を参照します。</p>',11)),d(a,{scenario:"settings",locale:"ja",title:"デモ: 設定"})])}const m=t(i,[["render",l]]);export{g as __pageData,m as default};
